    ('K8-V017', 305, 7791, '65bd84a260b4125f9eac835aee64039e', 'zahl', 'summe_mal_summe', null, $rbf${"wert": 24}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "19", "text": "das Glied x vergessen: 25 − 6", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "36", "text": "−6 als +6 gerechnet", "fehlbild": "fb.vorzeichen.falsches_zeichen", "regel": "rr.vorzeichen"}]$rbf$::jsonb),
    ('K8-V018', 305, 7792, '5586cab254f34653c9d3e43ba8753d7d', 'auswahl', 'summe_mal_summe', 'c3e02e2262e268f5be9f9f68540064a9', $rbf${"index": 3}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "die Teilfläche 10 als Seitenlänge genommen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "die Seiten aus 2 + 5 und 5 − 2 gebildet", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "2", "text": "nur ein Teil der Fläche", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V019', 305, 7793, '81619479b2fcd1ddc8b9f7f9a405313d', 'luecken', 'ausklammern', null, $rbf${"werte": [6, 2, 3]}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "luecke", "luecke": 1, "wert": "2", "text": "einen gemeinsamen Teiler genommen, aber nicht den größten", "fehlbild": null, "regel": null}, {"nr": 2, "art": "luecke", "luecke": 1, "wert": "3", "text": "einen gemeinsamen Teiler genommen, aber nicht den größten", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V020', 305, 7794, '811653bf1c21262dc13ccd2099f4b0dc', 'zahl', 'ausklammern', null, $rbf${"wert": 180}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "30", "text": "nur die Klammer 17 + 13 ausgerechnet", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "115", "text": "die 6 nur bei 17 gerechnet: 102 + 13", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V021', 305, 7795, 'cb7f7a24b04346a481da3a848b82f78f', 'zahl', 'ausklammern', null, $rbf${"wert": 375, "einheit": "€"}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "212.5", "text": "nur die T-Shirts gerechnet", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "15", "text": "nur die Klammer 8,50 + 6,50 gerechnet", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V022', 305, 7796, 'c59a8202baa0fbb66d5b8274fe29f587', 'luecken', 'binomisch', null, $rbf${"werte": [4, 12, 9, 49]}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "luecke", "luecke": 1, "wert": "2", "text": "die 2 in der Klammer nicht mitquadriert: 2a²", "fehlbild": "fb.potenz.basis_mal_hochzahl", "regel": "rr.potenz"}, {"nr": 2, "art": "luecke", "luecke": 3, "wert": "6", "text": "3 · 2 statt 3² gerechnet", "fehlbild": "fb.potenz.basis_mal_hochzahl", "regel": "rr.potenz"}, {"nr": 3, "art": "luecke", "luecke": 4, "wert": "109", "text": "das mittlere Glied vergessen: nur 4a² + 9 mit a = 5 gerechnet", "fehlbild": null, "regel": null}, {"nr": 4, "art": "luecke", "luecke": 4, "wert": "169", "text": "das mittlere Glied addiert statt abgezogen: 100 + 60 + 9", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V023', 305, 7797, '1599d9c1109d63c2d02755ed80a81719', 'zahl', 'binomisch', null, $rbf${"wert": 30}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "15", "text": "die 2 im doppelten Produkt vergessen: 3 · 5", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "8", "text": "3 + 5 gerechnet", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "-30", "text": "ein Minus eingefügt", "fehlbild": "fb.vorzeichen.falsches_zeichen", "regel": "rr.vorzeichen"}]$rbf$::jsonb),
    ('K8-V024', 305, 7798, 'ee64b67b7b789aad70da95250ea3a5c4', 'auswahl', 'binomisch', '151010f1e8ff08e4e3bd8504255e4e01', $rbf${"index": 1}$rbf$::jsonb, 'rr.ausmultiplizieren', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "das Mischglied vergessen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "2", "text": "nur eine der beiden Teilflächen 3a gezählt", "fehlbild": null, "regel": null}, {"nr": 3, "art": "index", "luecke": null, "wert": "3", "text": "3 · 2 statt 3² gerechnet", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V025', 305, 7799, '6593e0ea70bc8e0d2eb3797ada296688', 'auswahl', 'gleichungen_binomisch', '6cb911a71d07c5765726ebd2cb6fd197', $rbf${"index": 2}$rbf$::jsonb, 'rr.waage', $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "diese Zeile ist richtig; der Fehler steckt woanders", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "1", "text": "diese Zeile ist richtig; der Fehler steckt woanders", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V026', 305, 7800, '528f4d148a6cd711f677f406918976eb', 'zahl', 'gleichungen_binomisch', null, $rbf${"wert": 7, "einheit": "m"}$rbf$::jsonb, 'id.algebra.gleichung_loesen', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "8.5", "text": "51 : 6 gerechnet, die 9 vergessen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "17", "text": "das Mischglied nicht beachtet: 51 : 3", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('K8-V027', 305, 7801, 'aef6edaeb8ca00814992917e400e0bef', 'zahl', 'gleichungen_binomisch', null, $rbf${"wert": 17}$rbf$::jsonb, 'id.algebra.gleichung_loesen', $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "9", "text": "nur das letzte Glied 3² genommen", "fehlbild": null, "regel": null}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "33", "text": "das Glied 4x vergessen: 49 − 16", "fehlbild": null, "regel": null}]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      insert into schule.aufgabe_fehlbild (aufgabe_id, nr, art, luecke, wert, beschreibung, fehlbild, regel)
      values (a.id, (f->>'nr')::smallint, f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') on conflict do nothing;
      get diagnostics c = row_count; n_fb_neu := n_fb_neu + c;
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s steht schon anders da (oder gleicher Schlüssel unter anderer Nummer)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if coalesce(array_length(v_ids, 1), 0) <> 183
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 183
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 464 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 183)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
